import{z as p,x as B,o,c as d,q as E,j as i,D as n,d as r,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"信源编码定理","description":"","frontmatter":{"title":"信源编码定理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/source-coding-theorem.md","filePath":"cs/source-coding-theorem.md","lastUpdated":1791413859000}'),m={name:"cs/source-coding-theorem.md"};function A(f,a,h,H,u,c){const t=B("Mermaid");return o(),d("div",null,[a[2]||(a[2]=E('<h1 id="信源编码定理" tabindex="-1">信源编码定理 <a class="header-anchor" href="#信源编码定理" aria-label="Permalink to &quot;信源编码定理&quot;">​</a></h1><div class="epigraph"><p>i.i.d. 信源的压缩，平均每符号码长不能低于熵，也能任意接近熵；熵从此是可达到的下界，不是比喻。</p><footer>—— 据 Shannon, 1948；Cover and Thomas, Elements of Information Theory 整理</footer></div><p>复杂性单元在<a href="/cs/bqp-intuition">BQP</a> 收束。本单元换尺子。<a href="/cs/entropy-bits">熵</a> 已定义 \\(H(X)\\)，并声明压缩下界留给后课。缺口是<strong>信源编码定理</strong>（无噪声）：块长 \\(n\\to\\infty\\) 时，平均码长 \\(\\ge H\\)，且对任意 \\(\\varepsilon\\) 存在码 \\(\\lt H+\\varepsilon\\)。不重写自信息。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>符号来自分布 \\(p\\)，独立同分布。定长编码 \\(nH\\) 量级比特不够覆盖全部 \\(\\mathcal{X}^n\\)，但典型集大小约 \\(2^{nH}\\)，把非典型扔掉（小概率），即可用约 \\(nH\\) 比特编号典型串。变长前缀码：期望长度 \\(L\\) 满足 \\(H\\le L\\lt H+1\\)（Shannon 码、后课 Huffman）。定理的渐近形式用典型集；单符号形式用 Kraft 不等式。</p><p><a href="/cs/kolmogorov-complexity">Kolmogorov</a> 是单串最短程序；这里是分布上的期望码长。不要混。</p><p><span class="marginnote">术语翻译：典型集就是「自信息接近 \\(nH\\) 的那些长串」的集合。可以想象成把所有可能的 \\(n\\) 位结果按概率排座：绝大多数概率质量挤在约 \\(2^{nH}\\) 个座位上，只给这批编号，远比给全部座位编号划算。</span></p><h3 id="熵仍不是文件字节数" tabindex="-1">熵仍不是文件字节数 <a class="header-anchor" href="#熵仍不是文件字节数" aria-label="Permalink to &quot;熵仍不是文件字节数&quot;">​</a></h3><p>UTF-8 文件长度是某编码的实现。定理说：相对真正的 \\(p\\)，你不能系统性地压过 \\(H\\)。模型错了，\\(H\\) 算错，压缩器可以「看起来」压过错误模型的熵。</p><p><span class="marginnote">Shannon 1948 第 III 部分。Cover–Thomas 第 3、5 章。典型集：\\(-\\frac1n\\log p(x^n)\\approx H\\)。本课不把 AEP 证完，只锁定可达与不可达。</span></p><p><span class="marginnote">数字实例：设 \\(H(X)=0.8\\) 比特/符号。单符号整数码长最短是 1 比特，离熵差 0.2；把 100 个符号打包成块，给典型块 81 比特编号即可，摊到每符号 0.81 比特，差距缩到 0.01。块越长，这 1 比特的「凑整税」摊得越薄。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述：无损、i.i.d.、平均意义。画出典型集编号。点名 Kraft：前缀码长满足 \\(\\sum 2^{-\\ell_i}\\le 1\\)，从而 \\(L\\ge H\\)。下一课 Huffman 达到最优整数码长。</p>',13)),(o(),i(l,null,{default:n(()=>[s(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%88%86%E5%B8%83%20p%22%5D%20--%3E%20H%5B%22%E7%86%B5%20H(X)%22%5D%0A%20%20H%20--%3E%20TYP%5B%22%E5%85%B8%E5%9E%8B%E9%9B%86%20%E2%89%88%202%5E%7BnH%7D%22%5D%0A%20%20TYP%20--%3E%20CODE%5B%22%E5%B9%B3%E5%9D%87%E7%A0%81%E9%95%BF%20%E2%86%92%20H%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有了下界，后课 Huffman、算术、LZ 都是逼近 \\(H\\) 的构造，不是另起一种「信息量」。信道课将把噪声加回来：那里下界换成容量。本课信道是无噪声的：编码只为缩短，不为抗错。",-1)),a[5]||(a[5]=e("p",null,"块长换期望：单符号 Huffman 可能离 \\(H\\) 差将近 1 比特；\\(n\\) 块把差摊薄。",-1)),(o(),i(l,null,{default:n(()=>[s(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22n%20%E4%B8%AA%E7%AC%A6%E5%8F%B7%E6%89%93%E5%8C%85%E6%88%90%E4%B8%80%E5%9D%97%22%5D%20--%3E%20J%5B%22%E8%81%94%E5%90%88%E4%B8%B2%E7%9A%84%E8%81%94%E5%90%88%E7%86%B5%E7%BA%A6%20n%C2%B7H%22%5D%0A%20%20J%20--%3E%20T%5B%22%E5%85%B8%E5%9E%8B%E5%9D%97%E5%8F%AA%E5%8D%A0%E7%BA%A6%202%5E%7BnH%7D%20%E4%B8%AA%22%5D%0A%20%20T%20--%3E%20IDX%5B%22%E6%AF%8F%E5%9D%97%E7%BB%99%E7%BA%A6%20n%C2%B7H%20%E6%AF%94%E7%89%B9%E7%BC%96%E5%8F%B7%22%5D%0A%20%20IDX%20--%3E%20G%5B%22%E5%87%91%E6%95%B4%E8%AF%AF%E5%B7%AE%E4%B8%8D%E8%B6%B3%201%20%E6%AF%94%E7%89%B9%22%5D%0A%20%20G%20--%3E%20PER%5B%22%E6%91%8A%E5%88%B0%E6%AF%8F%E7%AC%A6%E5%8F%B7%E4%B8%8D%E8%B6%B3%201%2Fn%20%E6%AF%94%E7%89%B9%22%5D%0A%20%20PER%20--%3E%20N%5B%22n%20%E5%A2%9E%E5%A4%A7%20%E2%86%92%20%E7%A0%81%E9%95%BF%E4%BB%BB%E6%84%8F%E9%80%BC%E8%BF%91%20H%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p>这一张图回答的是：为什么块长变大能把平均码长逼到 \\(H\\)——凑整税按 \\(1/n\\) 衰减，而不是靠某个更聪明的单符号码。</p><p>渐近等分：几乎所有长串的概率在 \\(2^{-n(H\\pm\\varepsilon)}\\)。非典型集概率 \\(\\to 0\\)，故扔掉它们只损失可忽略的错误——无损版本用块末尾的溢出符号处理。有记忆源换成熵率 \\(H_\\infty\\)；本课 i.i.d. 足够让 Huffman/算术/LZ 有共同靶子。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不构造 Huffman，不谈有记忆信源的熵率（点名 \\(H(X_{n}|X^{n-1})\\)）。不引入有损。后课默认：无损压缩的一阶目标是 \\(H\\)。下一课 Huffman。</p><p>下界对真分布 \\(p\\) 生效；模型错了，你「压过熵」只是压过了错误的 \\(H(\\hat p)\\)。典型集解释块编码，Huffman 下一课给出单符号整数最优。</p><p><span class="marginnote">常见误区：初学者容易以为「压缩率压过熵」说明定理错了。实际上那只是说明你用的熵模型算错了——对真实分布 \\(p\\) 的熵是硬下界，被压过的只是错误模型 \\(\\hat p\\) 的 \\(H(\\hat p)\\)。这一步若想反了，后面评估压缩器时会系统性高估改进空间。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无损 i.i.d.：平均码长以 \\(H\\) 为下界且可逼近。</li><li>典型集解释「为什么不必给所有串留号」。</li><li>与 \\(K(x)\\) 分工：期望 vs 单串。</li><li>出处：Shannon, 1948；Cover and Thomas。</li></ul>',8))])}const T=p(m,[["render",A]]);export{_ as __pageData,T as default};
